// ══════════════ FIRESTORE HELPERS ══════════════
async function fetchEvidence(mechId) {
  try {
    const snap = await getDocs(query(collection(db,"evidence"), where("mechId","==",mechId)));
    return snap.docs.map(d=>({id:d.id,...d.data()}));
  } catch { return []; }
}
async function addEv(mechId, file, setMsg) {
  setMsg("جارٍ الرفع...");
  const cloud = await uploadToCloudinary(file, setMsg);
  const ref2  = doc(collection(db,"evidence"));
  const data  = { mechId, ...cloud, ts: Date.now() };
  await setDoc(ref2, data);
  setMsg(null);
  return { id: ref2.id, ...data };
}
async function delEv(item) {
  await deleteDoc(doc(db,"evidence",item.id));
}
async function fetchAllCounts() {
  const counts = {};
  try {
    const snap = await getDocs(collection(db,"evidence"));
    snap.docs.forEach(d => {
      const m = d.data().mechId;
      counts[m] = (counts[m]||0) + 1;
    });
  } catch {}
  return counts;
}
const totalM = () => DOMAINS.reduce((s,d)=>s+d.indicators.reduce((ss,i)=>ss+i.mechanisms.length,0),0);
const totalI = () => DOMAINS.reduce((s,d)=>s+d.indicators.length,0);
const fmtD   = ts => new Date(ts).toLocaleDateString("ar-SA",{year:"numeric",month:"short",day:"numeric"});

