// ══════════════ QUOTE TICKER ══════════════
function Quotes({dark}){
  const [i,setI]=useState(0);
  const [v,setV]=useState(true);
  useEffect(()=>{
    const t=setInterval(()=>{setV(false);setTimeout(()=>{setI(x=>(x+1)%QUOTES.length);setV(true);},500);},5000);
    return()=>clearInterval(t);
  },[]);
  return(
    <div className={`rounded-2xl p-5 text-center ${dark?"bg-slate-800/40 border border-white/5":"bg-white/80 border border-slate-100"}`}>
      <div className="text-3xl opacity-10 select-none mb-1">"</div>
      <p className={`text-sm leading-relaxed transition-all duration-500 ${v?"opacity-100":"opacity-0 translate-y-1"} ${dark?"text-slate-300":"text-slate-600"}`}>{QUOTES[i]}</p>
      <div className="flex justify-center gap-1.5 mt-3">
        {QUOTES.map((_,x)=><div key={x} className="rounded-full transition-all duration-300" style={{width:x===i?14:5,height:5,background:x===i?"#0d9488":"currentColor",opacity:x===i?1:0.2}}/>)}
      </div>
    </div>
  );
}

// ══════════════ FILE VIEWER ══════════════
function Viewer({file,onClose}){
  if(!file) return null;
  const isPdf=file.type==="application/pdf";
  const isImg=file.type?.startsWith("image/");
  return(
    <div className="fixed inset-0 z-50 flex items-center justify-center p-3" style={{background:"rgba(0,0,0,0.9)"}}>
      <div className="relative w-full max-w-4xl flex flex-col rounded-2xl overflow-hidden" style={{background:"#1e293b",maxHeight:"93vh"}}>
        <div className="flex items-center justify-between p-4 border-b border-white/10 flex-shrink-0">
          <span className="text-white text-sm font-medium truncate">{file.name}</span>
          <button onClick={onClose} className="p-2 rounded-lg hover:bg-white/10 text-white/60 hover:text-white"><I.X/></button>
        </div>
        <div className="flex-1 overflow-auto p-4 flex items-center justify-center" style={{minHeight:300}}>
          {isImg&&<img src={file.url} alt={file.name} className="max-w-full rounded-xl object-contain" style={{maxHeight:"70vh"}}/>}
          {isPdf&&<iframe src={file.url} title={file.name} className="w-full rounded-xl" style={{height:"70vh",border:"none"}}/>}
          {!isImg&&!isPdf&&<div className="text-white/50 text-center py-12"><div className="text-4xl mb-2">📄</div><p>معاينة غير متاحة</p></div>}
        </div>
      </div>
    </div>
  );
}

// ══════════════ MECHANISM CARD ══════════════
function MechCard({mech,dark,color,onCnt}){
  const [files,setFiles]=useState([]);
  const [load,setLoad]=useState(true);
  const [busy,setBusy]=useState(false);
  const [msg,setMsg]=useState(null);
  const [open,setOpen]=useState(false);
  const [view,setView]=useState(null);
  const fRef=useRef(); const cRef=useRef();

  useEffect(()=>{fetchEvidence(mech.id).then(f=>{setFiles(f);setLoad(false);});},[mech.id]);

  const add=useCallback(async list=>{
    const arr=Array.from(list); if(!arr.length) return;
    setBusy(true);
    const added=[];
    for(const f of arr){
      if(f.size>20*1024*1024){alert("الحد الأقصى 20 ميغابايت");continue;}
      try{ added.push(await addEv(mech.id,f,setMsg)); }
      catch(e){ console.error(e); alert("فشل الرفع — تأكد من إعدادات Cloudinary"); }
    }
    const up=[...files,...added];
    setFiles(up); onCnt(mech.id,up.length); setBusy(false); setMsg(null);
  },[files,mech.id,onCnt]);

  const del=useCallback(async item=>{
    setBusy(true); await delEv(item);
    const up=files.filter(f=>f.id!==item.id);
    setFiles(up); onCnt(mech.id,up.length); setBusy(false);
  },[files,mech.id,onCnt]);

  const has=files.length>0;
  return(
    <>
      {view&&<Viewer file={view} onClose={()=>setView(null)}/>}
      <div className="rounded-xl overflow-hidden transition-all duration-300"
        style={{background:dark?"rgba(30,41,59,0.85)":"rgba(255,255,255,0.95)",
          border:`1px solid ${has?color+"50":dark?"rgba(255,255,255,0.07)":"rgba(0,0,0,0.07)"}`,
          boxShadow:has?`0 4px 20px ${color}18`:undefined}}>
        <div className="flex items-start gap-3 p-4 cursor-pointer select-none" onClick={()=>setOpen(o=>!o)}>
          <div className="w-8 h-8 rounded-lg flex items-center justify-center text-white text-sm font-bold flex-shrink-0" style={{background:color}}>{mech.num}</div>
          <div className="flex-1 min-w-0">
            <p className={`text-sm leading-relaxed ${dark?"text-slate-200":"text-slate-800"}`}>{mech.text}</p>
            {mech.tool&&<p className="text-xs mt-1 opacity-50">🔧 {mech.tool}</p>}
          </div>
          <div className="flex items-center gap-2 flex-shrink-0">
            {busy&&<I.Spin/>}
            {has&&!busy&&<span className="text-xs px-2 py-0.5 rounded-full font-bold" style={{background:color+"22",color}}>{files.length}</span>}
            <span className={`transition-transform duration-200 opacity-30 ${open?"rotate-180":""}`}><I.Down/></span>
          </div>
        </div>
        {open&&(
          <div className={`border-t px-4 pb-4 pt-3 ${dark?"border-white/5":"border-black/5"}`}>
            {msg&&<div className="flex items-center gap-2 text-xs mb-3 px-3 py-2 rounded-lg" style={{background:color+"15",color}}><I.Spin/>{msg}</div>}
            <div className="flex flex-wrap gap-2 mb-3">
              <button onClick={()=>fRef.current?.click()} disabled={busy} className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-semibold text-white disabled:opacity-50" style={{background:color}}><I.Up/>رفع ملف</button>
              <button onClick={()=>cRef.current?.click()} disabled={busy} className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-semibold disabled:opacity-50 ${dark?"bg-white/10 text-slate-200":"bg-slate-100 text-slate-700"}`}><I.Cam/>تصوير</button>
              <input ref={fRef} type="file" accept="image/*,application/pdf" multiple className="hidden" onChange={e=>{add(e.target.files);e.target.value="";}}/>
              <input ref={cRef} type="file" accept="image/*" capture="environment" className="hidden" onChange={e=>{add(e.target.files);e.target.value="";}}/>
            </div>
            {load?<div className="flex items-center gap-2 text-xs opacity-50 py-3"><I.Spin/>جارٍ التحميل...</div>:
            has?(
              <div className="grid grid-cols-3 sm:grid-cols-4 gap-2">
                {files.map(f=>{
                  const isImg=f.type?.startsWith("image/");
                  return(
                    <div key={f.id} className={`relative group rounded-lg overflow-hidden ${dark?"bg-slate-700":"bg-slate-100"}`} style={{aspectRatio:"1"}}>
                      {isImg?<img src={f.url} alt={f.name} className="w-full h-full object-cover" loading="lazy"/>:
                        <div className="w-full h-full flex flex-col items-center justify-center gap-1"><div className="text-2xl">📄</div><p className="text-xs opacity-60 truncate w-full text-center px-1">{f.name?.split(".").pop()?.toUpperCase()}</p></div>}
                      <div className="absolute inset-0 bg-black/0 group-hover:bg-black/55 transition-all flex items-center justify-center gap-1.5 opacity-0 group-hover:opacity-100">
                        <button onClick={()=>setView(f)} className="p-1.5 rounded-lg bg-white/20 hover:bg-white/40 text-white"><I.Eye/></button>
                        <button onClick={()=>del(f)} className="p-1.5 rounded-lg bg-red-500/70 hover:bg-red-500 text-white"><I.Del/></button>
                      </div>
                    </div>
                  );
                })}
                <button onClick={()=>fRef.current?.click()} className={`rounded-lg border-2 border-dashed flex flex-col items-center justify-center gap-1 transition-colors ${dark?"border-white/10 hover:border-white/25 text-slate-500":"border-slate-200 hover:border-slate-300 text-slate-400"}`} style={{aspectRatio:"1"}}><I.Add/><span className="text-xs">إضافة</span></button>
              </div>
            ):(
              <div className={`rounded-xl border-2 border-dashed flex flex-col items-center justify-center py-8 gap-2 cursor-pointer transition-colors ${dark?"border-white/10 hover:border-white/20 text-slate-500":"border-slate-200 hover:border-slate-300 text-slate-400"}`}
                onDragOver={e=>{e.preventDefault();e.currentTarget.style.borderColor=color;}}
                onDragLeave={e=>{e.currentTarget.style.borderColor="";}}
                onDrop={e=>{e.preventDefault();e.currentTarget.style.borderColor="";add(e.dataTransfer.files);}}
                onClick={()=>fRef.current?.click()}>
                <div className="text-3xl opacity-40">📎</div>
                <p className="text-xs font-medium">اسحب وأفلت أو انقر للرفع</p>
                <p className="text-xs opacity-50">صور أو PDF — حتى 20 ميغابايت</p>
              </div>
            )}
            {has&&<p className="text-xs mt-2 opacity-40">آخر رفع: {fmtD(Math.max(...files.map(f=>f.ts)))}</p>}
          </div>
        )}
      </div>
    </>
  );
}

// ══════════════ INDICATOR PAGE ══════════════
function IndPage({ind,domain,dark,onBack,counts,setCounts}){
  const onCnt=useCallback((id,n)=>setCounts(p=>({...p,[id]:n})),[setCounts]);
  const total=ind.mechanisms.reduce((s,m)=>s+(counts[m.id]||0),0);
  const pct=Math.round(total/ind.mechanisms.length*100);
  return(
    <div className="max-w-3xl mx-auto px-4 py-6 au">
      <button onClick={onBack} className={`flex items-center gap-2 mb-4 text-sm transition-colors ${dark?"text-slate-400 hover:text-white":"text-slate-500 hover:text-slate-800"}`}><I.Back/>العودة إلى {domain.name}</button>
      <div className="rounded-2xl p-5 mb-5" style={{background:`linear-gradient(135deg,${domain.from},${domain.to})`}}>
        <div className="flex gap-3">
          <span className="text-3xl">{domain.icon}</span>
          <div className="flex-1">
            <p className="text-white/60 text-xs font-mono mb-1">{ind.code}</p>
            <h1 className="text-white font-bold text-sm leading-relaxed">{ind.text}</h1>
            <div className="flex gap-4 mt-2 text-white/70 text-xs"><span>{ind.mechanisms.length} آليات</span><span>{total} شاهد</span></div>
          </div>
        </div>
        {total>0&&(<div className="mt-3"><div className="flex justify-between text-white/60 text-xs mb-1"><span>نسبة الإنجاز</span><span>{pct}%</span></div><div className="h-2 rounded-full bg-white/20"><div className="h-full rounded-full bg-white/75 transition-all duration-700" style={{width:pct+"%"}}/></div></div>)}
      </div>
      <div className="space-y-3">{ind.mechanisms.map(m=><MechCard key={m.id} mech={m} dark={dark} color={domain.from} onCnt={onCnt}/>)}</div>
      <div className="mt-6"><Quotes dark={dark}/></div>
    </div>
  );
}

// ══════════════ DOMAIN PAGE ══════════════
function DomPage({domain,dark,onBack,onInd,counts}){
  const [q,setQ]=useState("");
  const list=domain.indicators.filter(i=>i.text.includes(q)||i.code.includes(q));
  const total=domain.indicators.reduce((s,i)=>s+i.mechanisms.reduce((ss,m)=>ss+(counts[m.id]||0),0),0);
  const totM=domain.indicators.reduce((s,i)=>s+i.mechanisms.length,0);
  const pct=Math.round(total/Math.max(totM,1)*100);
  return(
    <div className="max-w-3xl mx-auto px-4 py-6 au">
      <button onClick={onBack} className={`flex items-center gap-2 mb-4 text-sm ${dark?"text-slate-400 hover:text-white":"text-slate-500 hover:text-slate-800"}`}><I.Back/>الرئيسية</button>
      <div className="rounded-2xl p-6 mb-5" style={{background:`linear-gradient(135deg,${domain.from},${domain.to})`}}>
        <div className="text-4xl mb-3">{domain.icon}</div>
        <h1 className="text-white text-xl font-black mb-1">{domain.name}</h1>
        <p className="text-white/70 text-sm mb-4">{domain.description}</p>
        <div className="flex gap-6 mb-4">
          {[{v:domain.indicators.length,l:"مؤشر"},{v:totM,l:"آلية"},{v:total,l:"شاهد"}].map(s=>
            <div key={s.l}><div className="text-white text-xl font-black">{s.v}</div><div className="text-white/60 text-xs">{s.l}</div></div>)}
        </div>
        <div className="flex justify-between text-white/60 text-xs mb-1"><span>نسبة الإنجاز</span><span>{pct}%</span></div>
        <div className="h-2 rounded-full bg-white/20"><div className="h-full rounded-full bg-white/75 transition-all duration-700" style={{width:pct+"%"}}/></div>
      </div>
      <div className={`flex items-center gap-2 rounded-xl px-4 py-2.5 mb-4 ${dark?"bg-slate-800":"bg-white border border-slate-200"}`}>
        <I.Find/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="ابحث في المؤشرات..." className="flex-1 bg-transparent outline-none text-sm" style={{color:dark?"#e2e8f0":"#1e293b"}}/>
        {q&&<button onClick={()=>setQ("")}><I.X/></button>}
      </div>
      <div className="space-y-3">
        {list.map(ind=>{
          const t=ind.mechanisms.reduce((s,m)=>s+(counts[m.id]||0),0);
          const p=Math.round(t/ind.mechanisms.length*100);
          return(
            <button key={ind.id} onClick={()=>onInd(ind)} className={`w-full text-right rounded-xl p-4 transition-all hover:scale-[1.01] ${dark?"bg-slate-800/70 hover:bg-slate-800 border border-white/5":"bg-white hover:shadow-md border border-slate-100"}`}>
              <div className="flex items-start gap-3">
                <div className="flex-shrink-0">
                  {t>0?<div className="w-8 h-8 rounded-full flex items-center justify-center text-white" style={{background:domain.from}}><I.OK/></div>
                      :<div className={`w-8 h-8 rounded-full flex items-center justify-center text-xs font-bold ${dark?"bg-slate-700 text-slate-400":"bg-slate-100 text-slate-500"}`}>{ind.mechanisms.length}</div>}
                </div>
                <div className="flex-1 min-w-0">
                  <p className="text-xs font-mono opacity-40 mb-1">{ind.code}</p>
                  <p className={`text-sm leading-relaxed ${dark?"text-slate-200":"text-slate-700"}`}>{ind.text}</p>
                  <div className="flex items-center gap-3 mt-2">
                    <span className="text-xs opacity-40">{ind.mechanisms.length} آليات</span>
                    {t>0&&<span className="text-xs px-2 py-0.5 rounded-full font-bold" style={{background:domain.from+"22",color:domain.from}}>{t} شاهد · {p}%</span>}
                  </div>
                </div>
                <div className="opacity-25 flex-shrink-0"><I.Back/></div>
              </div>
            </button>
          );
        })}
        {!list.length&&<p className="text-center py-10 text-sm opacity-40">لا توجد نتائج</p>}
      </div>
      <div className="mt-6"><Quotes dark={dark}/></div>
    </div>
  );
}

// ══════════════ HERO ══════════════
function Hero({dark}){
  return(
    <div className="relative overflow-hidden rounded-3xl mb-7" style={{background:dark?"linear-gradient(135deg,#0f2027,#203a43,#2c5364)":"linear-gradient(135deg,#dbeafe,#bfdbfe,#e0e7ff)"}}>
      <div className="absolute inset-0 opacity-5" style={{backgroundImage:"radial-gradient(circle,white 1px,transparent 1px)",backgroundSize:"30px 30px"}}/>
      <div className="relative flex flex-col sm:flex-row items-center gap-5 p-6 sm:p-8">
        <div className="relative flex-shrink-0">
          <div className="absolute inset-0 rounded-full blur-xl opacity-40" style={{background:"#0d9488"}}/>
          <img src={LOGO} alt="شعار" className="relative w-24 h-24 sm:w-28 sm:h-28 object-contain rounded-full drop-shadow-2xl" style={{background:"white",padding:5}}/>
        </div>
        <div className="flex-1 text-center sm:text-right">
          <div className={`inline-flex items-center gap-2 px-3 py-1 rounded-full text-xs font-bold mb-2 ${dark?"bg-teal-500/20 text-teal-300":"bg-teal-100 text-teal-700"}`}>
            <span className="w-1.5 h-1.5 rounded-full bg-teal-500 animate-pulse inline-block"/>منصة التقييم المدرسي الذاتي
          </div>
          <h1 className={`text-xl sm:text-2xl font-black leading-tight mb-1 ${dark?"text-white":"text-slate-900"}`}>رحلة التميز في التقويم المدرسي</h1>
          <p className={`text-sm font-bold mb-4 ${dark?"text-teal-300":"text-teal-700"}`}>مجمع عبدالله بن عمر بالسلب</p>
          <div className="flex flex-wrap justify-center sm:justify-start gap-4">
            {[{r:"إعداد",n:"أ/ علي حكمي",c:"#0d9488"},{r:"مدير المدرسة",n:"أ/ يحيى حسن جباري",c:"#1d4ed8"}].map(p=>(
              <div key={p.n} className="flex items-center gap-2">
                <div className="w-7 h-7 rounded-full flex items-center justify-center text-white text-xs font-bold flex-shrink-0" style={{background:p.c}}>{p.n[3]}</div>
                <div className="text-right"><div className="text-xs opacity-50">{p.r}</div><div className={`text-xs font-bold ${dark?"text-slate-200":"text-slate-800"}`}>{p.n}</div></div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

// ══════════════ HOME ══════════════
function Home({dark,goDomain,counts,q,setQ}){
  const totalEv=Object.values(counts).reduce((s,v)=>s+v,0);
  const [res,setRes]=useState([]);
  useEffect(()=>{
    if(!q.trim()){setRes([]);return;}
    const r=[];
    DOMAINS.forEach(d=>d.indicators.forEach(i=>{if(i.text.includes(q)||i.code.includes(q))r.push({d,i});}));
    setRes(r.slice(0,8));
  },[q]);
  return(
    <div className="max-w-4xl mx-auto px-4 py-6 au">
      <Hero dark={dark}/>
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 mb-6">
        {[{l:"مجال",v:DOMAINS.length,i:"📂",c:"#1d4ed8"},{l:"مؤشر",v:totalI(),i:"📋",c:"#0d9488"},
          {l:"آلية",v:totalM(),i:"🔍",c:"#b45309"},{l:"شاهد مرفوع",v:totalEv,i:"📎",c:"#7c3aed"}].map(s=>(
          <div key={s.l} className={`rounded-2xl p-4 text-center ${dark?"bg-slate-800/60":"bg-white border border-slate-100"}`}>
            <div className="text-2xl mb-1">{s.i}</div>
            <div className="text-2xl font-black" style={{color:s.c}}>{s.v}</div>
            <div className={`text-xs mt-0.5 ${dark?"text-slate-400":"text-slate-500"}`}>{s.l}</div>
          </div>
        ))}
      </div>
      {q&&res.length>0&&(
        <div className={`rounded-2xl p-4 mb-5 ${dark?"bg-slate-800":"bg-white border border-slate-100"}`}>
          <p className={`text-sm font-bold mb-3 ${dark?"text-slate-300":"text-slate-700"}`}>نتائج البحث ({res.length})</p>
          <div className="space-y-1.5">
            {res.map(({d,i},idx)=>(
              <button key={idx} onClick={()=>goDomain(d,i)} className={`w-full text-right p-3 rounded-xl transition-all ${dark?"hover:bg-slate-700":"hover:bg-slate-50"}`}>
                <span className="text-xs opacity-40">{i.code} · {d.name}</span>
                <p className={`text-xs mt-0.5 ${dark?"text-slate-300":"text-slate-600"}`}>{i.text}</p>
              </button>
            ))}
          </div>
        </div>
      )}
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 mb-6">
        {DOMAINS.map(d=>{
          const ev=d.indicators.reduce((s,i)=>s+i.mechanisms.reduce((ss,m)=>ss+(counts[m.id]||0),0),0);
          const tot=d.indicators.reduce((s,i)=>s+i.mechanisms.length,0);
          const pct=Math.round(ev/Math.max(tot,1)*100);
          return(
            <button key={d.id} onClick={()=>goDomain(d)} className={`text-right rounded-2xl p-5 transition-all duration-300 hover:scale-[1.02] active:scale-[0.99] ${dark?"bg-slate-800/60 hover:bg-slate-800 border border-white/5":"bg-white hover:shadow-lg border border-slate-100"}`}>
              <div className="flex items-start justify-between mb-4">
                <div className="w-12 h-12 rounded-2xl flex items-center justify-center text-2xl shadow-lg" style={{background:`linear-gradient(135deg,${d.from},${d.to})`}}>{d.icon}</div>
                <div className="text-right">
                  {ev>0&&<div className="text-xs font-bold mb-1" style={{color:d.from}}>{ev} شاهد</div>}
                  <div className={`text-sm font-black ${pct>=50?"text-emerald-500":pct>0?"text-amber-500":"opacity-25"}`}>{pct}%</div>
                </div>
              </div>
              <h3 className={`font-black text-base mb-1 ${dark?"text-white":"text-slate-900"}`}>{d.name}</h3>
              <p className={`text-xs mb-4 leading-relaxed ${dark?"text-slate-400":"text-slate-500"}`}>{d.description}</p>
              <div className={`h-1.5 rounded-full mb-3 ${dark?"bg-slate-700":"bg-slate-100"}`}>
                <div className="h-full rounded-full transition-all duration-700" style={{width:Math.min(pct,100)+"%",background:`linear-gradient(90deg,${d.from},${d.to})`}}/>
              </div>
              <div className="flex gap-4">
                <span className="text-xs opacity-40">{d.indicators.length} مؤشر</span>
                <span className="text-xs opacity-40">{tot} آلية</span>
              </div>
            </button>
          );
        })}
      </div>
      <Quotes dark={dark}/>
    </div>
  );
}

// ══════════════ APP ══════════════
export default function App(){
  const [dark,setDark]=useState(true);
  const [view,setView]=useState("home");
  const [domain,setDomain]=useState(null);
  const [ind,setInd]=useState(null);
  const [counts,setCounts]=useState({});
  const [q,setQ]=useState("");

  useEffect(()=>{fetchAllCounts().then(setCounts);},[]);

  const goDomain=useCallback((d,i=null)=>{
    setDomain(d);
    if(i){setInd(i);setView("ind");}
    else{setInd(null);setView("domain");}
  },[]);

  const bg=dark?"#0a1628":"#f1f5f9";
  const hdr=dark?"rgba(10,22,40,0.92)":"rgba(248,250,252,0.92)";

  return(
    <div dir="rtl" style={{minHeight:"100vh",background:bg,color:dark?"#e2e8f0":"#1e293b",fontFamily:"'Segoe UI',Tahoma,Arial,sans-serif",transition:"background 0.3s"}}>
      <style>{CSS}</style>
      <header className="sticky top-0 z-40 backdrop-blur-xl border-b" style={{background:hdr,borderColor:dark?"rgba(255,255,255,0.05)":"rgba(0,0,0,0.06)"}}>
        <div className="max-w-4xl mx-auto px-4 h-14 flex items-center gap-3">
          {view!=="home"&&<button onClick={()=>{if(view==="ind"){setView("domain");setInd(null);}else{setView("home");setDomain(null);}}} className={`p-2 rounded-xl ${dark?"hover:bg-white/10":"hover:bg-black/05"}`}><I.Back/></button>}
          {view==="home"?(
            <>
              <img src={LOGO} alt="" className="w-7 h-7 rounded-full object-contain flex-shrink-0" style={{background:"white",padding:1}}/>
              <div className={`flex-1 flex items-center gap-2 px-3 py-1.5 rounded-xl ${dark?"bg-white/5":"bg-black/05"}`}>
                <I.Find/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="ابحث في المؤشرات..." className="flex-1 bg-transparent outline-none text-sm" style={{color:dark?"#cbd5e1":"#475569"}}/>
                {q&&<button onClick={()=>setQ("")}><I.X/></button>}
              </div>
            </>
          ):(
            <div className="flex-1 flex items-center gap-2 min-w-0">
              {domain&&<div className="w-6 h-6 rounded-lg flex items-center justify-center text-sm flex-shrink-0" style={{background:`linear-gradient(135deg,${domain.from},${domain.to})`}}>{domain.icon}</div>}
              <h2 className="font-bold text-sm truncate">{view==="domain"?domain?.name:ind?.code}</h2>
            </div>
          )}
          <button onClick={()=>setDark(d=>!d)} className={`p-2 rounded-xl flex-shrink-0 ${dark?"hover:bg-white/10 text-slate-400":"hover:bg-black/05 text-slate-500"}`}>{dark?<I.Sun/>:<I.Moon/>}</button>
        </div>
      </header>
      <main>
        {view==="home"&&<Home dark={dark} goDomain={goDomain} counts={counts} q={q} setQ={setQ}/>}
        {view==="domain"&&domain&&<DomPage domain={domain} dark={dark} onBack={()=>setView("home")} onInd={i=>{setInd(i);setView("ind");}} counts={counts}/>}
        {view==="ind"&&domain&&ind&&<IndPage ind={ind} domain={domain} dark={dark} onBack={()=>setView("domain")} counts={counts} setCounts={setCounts}/>}
      </main>
      <div style={{height:40}}/>
    </div>
  );
}
